class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        int lo = *max_element(weights.begin(), weights.end());
        int hi = accumulate(weights.begin(), weights.end(), 0);
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int need = 1, load = 0;
            for (int i = 0; i < (int)weights.size(); i++) {
                if (load + weights[i] > mid) {
                    need++;
                    load = 0;
                }
                load += weights[i];
            }
            if (need <= days) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
